  3	final class IntArrayHeap {
  4	
  5	    private final int[] values;
  6	    private final int size;
  7	
  8	    private IntArrayHeap(int[] values) {
  9	        this.values = requireValues(values);
 10	        this.size = values.length;
 11	    }
 12	
 13	    static IntArrayHeap wrap(int[] values) {
 14	        return new IntArrayHeap(values);
 15	    }
 16	
 17	    static IntArrayHeap copyOf(int[] values) {
 18	        int[] copiedValues = Arrays.copyOf(requireValues(values), values.length);
 19	        return new IntArrayHeap(copiedValues);
 20	    }
 21	
 22	    IntArrayHeap buildMaxHeap() {
 23	        if (size < 2) {
 24	            return this;
 25	        }
 26	
 27	        for (int parentIndex = lastParentIndex(); parentIndex >= 0; parentIndex--) {
 28	            siftDown(parentIndex);
 29	        }
 30	
 31	        return this;
 32	    }
 33	
 34	    boolean isMaxHeap() {
 35	        for (int parentIndex = 0; parentIndex <= lastParentIndex(); parentIndex++) {
 36	            if (hasGreaterChild(parentIndex, leftChildIndex(parentIndex))) {
 37	                return false;
 38	            }
 39	
 40	            if (hasGreaterChild(parentIndex, rightChildIndex(parentIndex))) {
 41	                return false;
 42	            }
 43	        }
 44	
 45	        return true;
 46	    }
 47	
 48	    int[] toArray() {
 49	        return values;
 50	    }
 51	
 52	    private void siftDown(int parentIndex) {
 53	        int currentIndex = parentIndex;
 54	
 55	        while (true) {
 56	            int largestIndex = currentIndex;
 57	            largestIndex = largerIndex(largestIndex, leftChildIndex(currentIndex));
 58	            largestIndex = largerIndex(largestIndex, rightChildIndex(currentIndex));
 59	
 60	            if (largestIndex == currentIndex) {
 61	                return;
 62	            }
 63	
 64	            swap(currentIndex, largestIndex);
 65	            currentIndex = largestIndex;
 66	        }
 67	    }
 68	
 69	    private boolean hasGreaterChild(int parentIndex, int childIndex) {
 70	        return childIndex < size && values[parentIndex] < values[childIndex];
 71	    }
 72	
 73	    private int largerIndex(int currentLargestIndex, int candidateIndex) {
 74	        if (candidateIndex < size && values[candidateIndex] > values[currentLargestIndex]) {
 75	            return candidateIndex;
 76	        }
 77	
 78	        return currentLargestIndex;
 79	    }
 80	
 81	    private int lastParentIndex() {
 82	        return (size / 2) - 1;
 83	    }
 84	
 85	    private int leftChildIndex(int parentIndex) {
 86	        return (2 * parentIndex) + 1;
 87	    }
 88	
 89	    private int rightChildIndex(int parentIndex) {
 90	        return (2 * parentIndex) + 2;
 91	    }
 92	
 93	    private void swap(int firstIndex, int secondIndex) {
 94	        int temp = values[firstIndex];
 95	        values[firstIndex] = values[secondIndex];
 96	        values[secondIndex] = temp;
 97	    }
 98	
 99	    private static int[] requireValues(int[] values) {
100	        if (values == null) {
101	            throw new IllegalArgumentException("values must not be null");
102	        }
103	
104	        return values;
105	    }
106	}

